<div class="page-heading split"><div><p class="eyebrow">Reusable content</p><h1>Message templates</h1><p class="muted">Keep content consistent; order is preserved for every recipient.</p></div><a class="button" href="#new-template">New template</a></div>
<div class="notice notice-info"><strong>Provider rules:</strong> WhatsApp business-initiated messages generally need an approved provider template and must follow the messaging-window policy. Set the provider template name when required; your delivery adapter must enforce current Meta/provider rules.</div>
<div class="two-col section-block"><section class="panel"><h2>Your templates</h2><?php if(!$templates): ?><div class="empty-card"><h3>Nothing here yet</h3><p>Create text or mixed-media content once and reuse it across campaigns.</p></div><?php else: ?><div class="template-list"><?php foreach($templates as $t): ?><article class="template-card"><div><span class="badge"><?= e(strtoupper($t['language'])) ?></span><h3><?= e($t['name']) ?></h3><p class="muted"><?= count($t['parts']) ?> ordered part<?= count($t['parts'])===1?'':'s' ?><?php if($t['provider_template_name']): ?> · Provider: <?= e($t['provider_template_name']) ?><?php endif; ?></p><ol class="part-preview"><?php foreach($t['parts'] as $part): ?><li><strong><?= e(ucfirst($part['type'])) ?>:</strong> <?= e($part['text']?:('Media #'.$part['media_id'])) ?><?= $part['caption']?' — '.e($part['caption']):'' ?></li><?php endforeach; ?></ol></div><div class="actions"><form method="post" action="<?= e(url('templates/duplicate')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$t['id'] ?>"><button class="button button-small button-secondary" type="submit">Duplicate</button></form><form method="post" action="<?= e(url('templates/delete')) ?>" data-confirm="Delete this template? Existing campaign snapshots are preserved."><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$t['id'] ?>"><button class="button button-small button-danger" type="submit">Delete</button></form></div></article><?php endforeach; ?></div><?php endif; ?></section>
<aside class="stack"><section class="panel" id="new-template"><h2>Create a template</h2><form method="post" action="<?= e(url('templates/create')) ?>" class="stack"><?= csrf_field() ?><label for="template-name">Name</label><input id="template-name" name="name" required maxlength="140" placeholder="e.g. New season announcement"><label for="template-language">Language</label><input id="template-language" name="language" value="en" maxlength="16" required><label for="provider-name">Approved provider template <span class="muted">(optional)</span></label><input id="provider-name" name="provider_template_name" maxlength="120" placeholder="e.g. order_update_en"><fieldset><legend>Ordered message parts</legend><div id="template-parts" class="stack"><div class="template-part panel"><label>Part type<select class="part-type"><option value="text">Text</option><option value="image">Image</option><option value="audio">Audio</option><option value="document">Document</option></select></label><label class="part-text-label">Text<textarea class="part-text" rows="4" maxlength="5000" required placeholder="Write a useful message and include an opt-out instruction."></textarea></label><label class="part-media-label" hidden>Private media<select class="part-media"><option value="">Choose uploaded media</option><?php foreach($media as $m): ?><option value="<?= (int)$m['id'] ?>" data-type="<?= e($m['media_type']) ?>"><?= e($m['original_name']) ?> (<?= e($m['media_type']) ?>)</option><?php endforeach; ?></select></label><label class="part-caption-label" hidden>Caption <input class="part-caption" maxlength="1024"></label><button class="button button-small button-secondary remove-part" type="button">Remove part</button></div></div><button class="button button-small button-secondary" id="add-template-part" type="button">Add another part</button></fieldset><input type="hidden" name="parts_json" id="parts-json"><p class="hint">Choose text or uploaded media for each part; the displayed order is the dispatch order.</p><button class="button" type="submit">Save template</button></form></section>
<section class="panel"><h2>Private media library</h2><form method="post" action="<?= e(url('media/upload')) ?>" enctype="multipart/form-data" class="stack"><?= csrf_field() ?><label for="media-file">Image, audio or document</label><input id="media-file" name="media" type="file" accept="image/jpeg,image/png,image/gif,image/webp,audio/mpeg,audio/mp4,audio/ogg,audio/wav,audio/webm,application/pdf,.doc,.docx,.txt" required><p class="hint">Private to your account. 15 MB maximum. Image, audio and document formats only.</p><button class="button button-secondary" type="submit">Upload media</button></form><?php if($media): ?><ul class="media-list"><?php foreach($media as $m): ?><li><span class="badge"><?= e($m['media_type']) ?></span> <?= e($m['original_name']) ?> <span class="muted small">(<?= number_format((int)$m['size_bytes']/1024,0) ?> KB)</span></li><?php endforeach; ?></ul><?php else: ?><p class="muted">No media uploaded.</p><?php endif; ?></section></aside></div>
<script>
document.addEventListener('DOMContentLoaded',()=>{const form=document.querySelector('form[action$="templates/create"]'),list=document.querySelector('#template-parts'),add=document.querySelector('#add-template-part');if(!form||!list||!add)return;const sync=part=>{const type=part.querySelector('.part-type').value,isText=type==='text';part.querySelector('.part-text-label').hidden=!isText;part.querySelector('.part-text').required=isText;part.querySelector('.part-media-label').hidden=isText;part.querySelector('.part-caption-label').hidden=isText;part.querySelector('.part-media').required=!isText;for(const option of part.querySelector('.part-media').options)option.hidden=!!option.value&&option.dataset.type!==type;};const bind=part=>{part.querySelector('.part-type').addEventListener('change',()=>sync(part));part.querySelector('.remove-part').addEventListener('click',()=>{if(list.children.length>1)part.remove();});sync(part);};bind(list.firstElementChild);add.addEventListener('click',()=>{const clone=list.firstElementChild.cloneNode(true);clone.querySelector('.part-text').value='';clone.querySelector('.part-media').value='';clone.querySelector('.part-caption').value='';list.append(clone);bind(clone);clone.querySelector('.part-type').focus();});form.addEventListener('submit',()=>{const parts=[...list.querySelectorAll('.template-part')].map((part,i)=>{const type=part.querySelector('.part-type').value;return type==='text'?{sequence:i+1,type,text:part.querySelector('.part-text').value.trim()}:{sequence:i+1,type,media_id:Number(part.querySelector('.part-media').value),caption:part.querySelector('.part-caption').value.trim()||null};});form.querySelector('#parts-json').value=JSON.stringify(parts);});});
</script>
